import json
import pandas as pd
from sklearn.preprocessing import MinMaxScaler
import matplotlib.pyplot as plt

def task_func(json_data: str, data_key: str):
    def parse_path(path):
        if path == "":
            return []
        parts = []
        for piece in path.split("."):
            if piece == "":
                raise KeyError(data_key)
            parts.append(piece)
        return parts

    def get_by_path(obj, path):
        current = obj
        for key in path:
            if isinstance(current, dict):
                if key not in current:
                    raise KeyError(data_key)
                current = current[key]
            elif isinstance(current, list):
                try:
                    idx = int(key)
                except (TypeError, ValueError):
                    raise KeyError(data_key)
                if idx < 0 or idx >= len(current):
                    raise KeyError(data_key)
                current = current[idx]
            else:
                raise KeyError(data_key)
        return current

    data = json.loads(json_data)
    raw_values = get_by_path(data, parse_path(data_key))

    if raw_values is None:
        values = []
    elif isinstance(raw_values, dict):
        values = list(raw_values.values())
    elif isinstance(raw_values, (list, tuple)):
        values = raw_values
    else:
        values = [raw_values]

    original = pd.Series(pd.to_numeric(pd.Series(values), errors="raise"), dtype="float64")

    if original.empty:
        return original, None, None

    scaler = MinMaxScaler()
    normalized_values = scaler.fit_transform(original.to_numpy().reshape(-1, 1)).ravel()
    normalized = pd.Series(normalized_values, index=original.index, dtype="float64")

    fig, ax = plt.subplots()
    ax.plot(original.index, original.values, label="Original Data")
    ax.plot(normalized.index, normalized.values, label="Normalized Data")
    ax.set_title("Comparison of Original and Normalized Data")
    ax.set_xlabel("Index")
    ax.set_ylabel("Value")
    ax.legend()

    return original, normalized, ax
